'use strict';
let pdfDBPromise;
function materialDB(){return pdfDBPromise??=new Promise((resolve,reject)=>{const r=indexedDB.open('english-flow-materials',2);r.onupgradeneeded=()=>{if(!r.result.objectStoreNames.contains('documents'))r.result.createObjectStore('documents',{keyPath:'id'});const pages=r.result.objectStoreNames.contains('pages')?r.transaction.objectStore('pages'):r.result.createObjectStore('pages',{keyPath:'id'});if(!pages.indexNames.contains('documentId'))pages.createIndex('documentId','documentId')};r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(Error('无法打开本机资料存储'))})}
async function materialAction(store,mode,action){const db=await materialDB();return new Promise((resolve,reject)=>{const tx=db.transaction(store,mode),r=action(tx.objectStore(store));let value;r.onsuccess=()=>value=r.result;tx.oncomplete=()=>resolve(value);tx.onerror=()=>reject(tx.error);tx.onabort=()=>reject(tx.error)})}
const builtinReferences=references;
references=async function(year){const existing=await builtinReferences(year);if(existing.length)return existing;const docs=await materialAction('documents','readonly',s=>s.getAll()).catch(()=>[]),doc=docs.find(d=>d.year===year&&d.status==='complete'&&!d.deleted);if(!doc)return [];const rows=(await materialAction('pages','readonly',s=>s.index('documentId').getAll(doc.id))).sort((a,b)=>a.page-b.page);const refs=rows.map(p=>{const image=URL.createObjectURL(p.blob);U.urls.push(image);return {...p,image}});U.refs.set(year,refs);return refs};
let pdfController=null;
async function importPDF(file,year,resumeId=null){if(pdfController){toast('正在处理解析，请先取消');return}if(!file||file.size>30*1024*1024||(!/\.pdf$/i.test(file.name)&&file.type!=='application/pdf')){toast('请选择 30 MB 以内的 PDF');return}const bytes=await file.arrayBuffer();if(new TextDecoder().decode(bytes.slice(0,5))!=='%PDF-'){toast('文件不是有效 PDF');return}if(!Number.isInteger(year)||year<2010||year>2026){toast('年份应为 2010—2026');return}const id=await sha(bytes),old=await materialAction('documents','readonly',s=>s.get(id)).catch(()=>null);if(old?.status==='complete'&&!old.deleted){toast('这份解析已导入，未重复处理');return}pdfController=new AbortController();const signal=pdfController.signal;dialog('导入解析 PDF','<p>文件与页面索引只保存在本机。扫描页先尝试本地 OCR；当前 OCR 以英文检索为主，原书中文仍按图片显示。</p><p id="pdfProgress" role="status">读取文件…</p><button id="cancelPDF">取消并保留进度</button>');$('#cancelPDF').onclick=()=>{pdfController?.abort();if(U.worker){U.worker.terminate();U.worker=null}};let pdf;try{const pdfjs=await import('./vendor/pdf.min.mjs');pdfjs.GlobalWorkerOptions.workerSrc=new URL('vendor/pdf.worker.min.mjs',location.href).href;pdf=await pdfjs.getDocument({data:new Uint8Array(bytes),isEvalSupported:false}).promise;if(pdf.numPages>100)throw Error('最多支持 100 页，请拆分 PDF 后导入');const doc={id,year,name:file.name,blob:file,status:'processing',pages:pdf.numPages,nextPage:old?.nextPage||1,createdAt:old?.createdAt||new Date().toISOString(),deleted:false};await materialAction('documents','readwrite',s=>s.put(doc));for(let n=doc.nextPage;n<=pdf.numPages;n++){if(signal.aborted)throw cancelled();$('#pdfProgress').textContent='正在建立第 '+n+' / '+pdf.numPages+' 页索引';const page=await pdf.getPage(n),viewport=page.getViewport({scale:1}),scale=Math.min(2,1400/viewport.width),v=page.getViewport({scale}),c=document.createElement('canvas');c.width=Math.ceil(v.width);c.height=Math.ceil(v.height);const render=page.render({canvasContext:c.getContext('2d'),viewport:v});const cancel=()=>render.cancel();signal.addEventListener('abort',cancel,{once:true});await render.promise;signal.removeEventListener('abort',cancel);const content=await page.getTextContent();let text=content.items.map(i=>i.str||'').join(' '),textSource='pdf-text';if(text.replace(/\s/g,'').length<30){const w=await worker(signal);const result=await raceAbort(w.recognize(c,{},{text:true}),signal);text=result.data.text;textSource='ocr-english-only'}const blob=await new Promise(resolve=>c.toBlob(resolve,'image/webp',.7));if(!blob)throw Error('页面图像保存失败');await materialAction('pages','readwrite',s=>s.put({id:id+':'+n,documentId:id,year,page:n,blob,text,textSource,source:file.name,questionNumbers:[...text.matchAll(/\b([1-4]?\d)[.．]/g)].map(m=>Number(m[1]))}));doc.nextPage=n+1;await materialAction('documents','readwrite',s=>s.put(doc));page.cleanup();c.width=1;c.height=1}doc.status='complete';await materialAction('documents','readwrite',s=>s.put(doc));U.refs.delete(year);toast('解析已导入本机，可从资料管理中打开');managePDFs()}catch(e){if($('#pdfProgress'))$('#pdfProgress').textContent=e.name==='AbortError'||signal.aborted?'已取消，重新选择相同 PDF 可从保存的页码继续。':'导入失败：'+e.message+'。已保存的进度保留，可重试。'}finally{pdfController=null;await pdf?.destroy()}}
async function managePDFs(){try{const docs=await materialAction('documents','readonly',s=>s.getAll());dialog('本机解析资料',docs.length?docs.map((d,i)=>'<div class="vocab-card"><strong>'+esc(d.name)+'</strong><p>'+d.year+' 年 · '+(d.deleted?'已移至回收区':d.status==='complete'?'已完成 '+d.pages+' 页':'已处理 '+(d.nextPage-1)+' 页，可重新选择原 PDF 续传')+'</p><button data-pdf-open="'+i+'" '+(d.deleted||d.status!=='complete'?'disabled':'')+'>连续阅读</button> <button data-pdf-trash="'+i+'">'+(d.deleted?'恢复':'移至回收区')+'</button></div>').join(''):'尚未导入解析 PDF。');document.querySelectorAll('[data-pdf-trash]').forEach(b=>b.onclick=async()=>{const d=docs[Number(b.dataset.pdfTrash)];d.deleted=!d.deleted;await materialAction('documents','readwrite',s=>s.put(d));U.refs.delete(d.year);managePDFs()});document.querySelectorAll('[data-pdf-open]').forEach(b=>b.onclick=async()=>{const d=docs[Number(b.dataset.pdfOpen)],rows=(await materialAction('pages','readonly',s=>s.index('documentId').getAll(d.id)));U.refs.set(d.year,rows.map(p=>({...p,image:URL.createObjectURL(p.blob)})));if(!U.page||U.page.year!==d.year)await openPage(U.pages.find(p=>p.year===d.year));$('#dialog').close();U.refPage=1;renderReference();const tag=$('#detailContent .source-tag');if(tag)tag.textContent='用户导入原书 · '+d.name;mobilePane('review')})}catch(e){toast('无法读取本机解析：'+e.message)}}
globalThis.managePDFs=managePDFs;
$('#importPDF').onclick=()=>{dialog('选择解析资料','<p>内置解析优先使用；同一 PDF 按内容哈希去重。</p><label>年份 <input id="pdfYear" type="number" min="2010" max="2026" value="'+(U.page?.year||2023)+'"></label><input id="pdfFile" type="file" accept="application/pdf,.pdf"><button id="pdfManage">管理已导入解析</button>');$('#pdfFile').onchange=e=>importPDF(e.target.files[0],Number($('#pdfYear').value));$('#pdfManage').onclick=managePDFs};
// Without a vision service, guesses remain unconfirmed and cannot affect scoring.
function localCandidates(photo,page){const numbers=page.page===1?Array.from({length:20},(_,i)=>i+1):(page.questions||[]).map(q=>q.number);return numbers.map(number=>({number,answer:null,candidates:[],confidence:0,ink:'未自动核验',evidence:'本地印刷 OCR 不能可靠区分黑笔原答、红笔订正与涂改，请对照照片确认。',requiresConfirmation:true}))}
function confirmAnswers(){if(!U.page){toast('请先打开一套题');return}const photo=F.photos.find(p=>p.pageId===U.page.id)||U.photo,rows=localCandidates(photo,U.page),year=U.page.year;if(!rows.length){toast('请打开题目页，正文页可从题号目录选择');return}dialog('答案识别确认','<p class="error-box">当前没有视觉模型服务。以下答案均未自动识别，默认不判错；请对照黑笔原答填写，红笔订正不作为原始答案。</p>'+(photo?'<img class="photo-preview" src="'+esc(photo.url)+'" alt="核对原始作答">':'')+'<div id="confirmRows">'+rows.map(r=>'<div class="confirm-row confidence-low"><strong>第 '+r.number+' 题 · 需人工确认</strong><label>原始答案 <select data-confirm-answer="'+r.number+'"><option value="">未作答 / 无法判断</option>'+('ABCD').split('').map(a=>'<option>'+a+'</option>').join('')+'</select></label><label><input type="checkbox" data-confirm-checked="'+r.number+'"> 我已核对</label><small>'+esc(r.evidence)+'</small></div>').join('')+'</div><button id="confirmAll">确认已填写的答案</button><p id="confirmationResult" role="status"></p>');$('#confirmAll').onclick=()=>{let count=0;for(const r of rows){const answer=document.querySelector('[data-confirm-answer="'+r.number+'"]').value,checked=document.querySelector('[data-confirm-checked="'+r.number+'"]').checked;if(!answer||!checked)continue;const key=year+'-'+r.number;U.records[key]={...(U.records[key]||{note:''}),answer,updatedAt:new Date().toISOString()};flowData.confirmed[key]={answer,confidence:null,recognitionConfidence:0,method:'manual-review',confirmedAt:new Date().toISOString()};count++}saveRecords();saveFlow();$('#confirmationResult').textContent='已保存 '+count+' 题；未勾选项目未参与统计。';renderQuestions()}}
$('#scanAnswers').onclick=confirmAnswers;
function stopPDF(){if(pdfController){pdfController.abort();if(U.worker){U.worker.terminate();U.worker=null}}}
$('#closeDialog').addEventListener('click',stopPDF);$('#dialog').addEventListener('cancel',stopPDF);
// Codex allowance is not an API credential: never route clicks to an invented AI endpoint.
apiConfig=async()=>({available:false,mode:'codex-context-handoff',models:{translation:'由当前 Codex 翻译阶段配置',chat:'在 Codex 中选择',analysis:'在 Codex 中选择',review:'在 Codex 中选择'}});
modelLabel=async()=>{$('#modelLabel').textContent='本站不自动调用模型。导出当前题上下文，在 Codex 中提问，再把答复粘贴回来保存。';$('#chatDepth').hidden=true;$('#chatKind').hidden=true};
sendChat=async function(){const text=$('#chatInput').value.trim();if(!text)return;const history=flowData.chats[F.chatKey]??=[];history.push({role:'user',text,at:new Date().toISOString()});saveFlow();drawChat();const context=chatContext();const prompt='请根据下列考研英语上下文回答我的问题。只引用提供的来源；没有可靠标准答案或解析文字时明确说明，不猜测。区分原书解析与 AI 补充。\n\n问题：'+text+'\n\n'+JSON.stringify(context,null,2);$('#handoffText').value=prompt;$('#handoffBox').hidden=false;$('#chatInput').value=''};
const handoff=make('details');handoff.id='handoffBox';handoff.hidden=true;handoff.open=true;handoff.innerHTML='<summary>本题上下文 · 复制到 Codex</summary><textarea id="handoffText" readonly aria-label="可复制的本题上下文" style="width:100%;height:120px"></textarea><button id="copyContext">复制上下文</button><textarea id="codexReply" maxlength="30000" placeholder="将 Codex 的答复粘贴到这里，本题单独保存" aria-label="保存 Codex 答复" style="width:100%;height:100px"></textarea><button id="saveCodexReply">保存 AI 补充答复</button>';
$('.chat-compose').prepend(handoff);$('#chatSend').textContent='整理问题与上下文';$('#chatStop').hidden=true;$('#chatRetry').hidden=true;$('#copyContext').onclick=async()=>{try{await navigator.clipboard.writeText($('#handoffText').value);toast('已复制，请粘贴到 Codex')}catch{$('#handoffText').select();toast('请手动复制选中的上下文')}};$('#saveCodexReply').onclick=()=>{const text=$('#codexReply').value.trim();if(!text)return;flowData.chats[F.chatKey]??=[];flowData.chats[F.chatKey].push({role:'assistant',text,origin:'user-pasted-codex',at:new Date().toISOString()});saveFlow();drawChat();$('#codexReply').value=''};
const originalPrivacy=privacy;privacy=function(){originalPrivacy();$('#dialogBody').querySelectorAll('p')[1].textContent='点读、印刷文字 OCR 与 PDF 导入不调用 AI。当前版本不联网调用模型；仅在你主动复制上下文并粘贴到 Codex 时，才会在 Codex 中进行分析。'};
const originalOpenChat=openChat;openChat=async function(kind){await originalOpenChat(kind);$('#chatContext').textContent='不会自动发送。生成的上下文只包含当前题原文、确认答案与少量相关解析文字。复制前可以检查。';$('#handoffBox').hidden=true;$('#codexReply').value=''};
